233. 	if len(c.ForbiddenAccountIds) > 0 {
234. 		for _, forbiddenAccountID := range c.ForbiddenAccountIds {
235. 			if accountID == forbiddenAccountID {
236. 				return fmt.Errorf("AWS account ID not allowed: %s", accountID)
237. 			}
238. 		}
239. 	}
240. 	if len(c.AllowedAccountIds) > 0 {
241. 		found := false
242. 		for _, allowedAccountID := range c.AllowedAccountIds {
243. 			if accountID == allowedAccountID {
244. 				found = true
245. 				break
246. 			}
247. 		}
248. 		if !found {
